<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowDown, ArrowUp, Check, Plus, Save, ShoppingCart, Trash2, X } from 'lucide-vue-next'
import JalaliDatePicker from '../components/JalaliDatePicker.vue'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import { purchasesApi, type PurchasePayload, type PurchaseRecord } from '../api/purchases'
import type { SupplierRecord } from '../api/suppliers'
import type { MaterialRecord } from '../api/materials'
import { formatMoney, type CurrencyUnit } from '../utils/currency'
import { currentCanonicalDate, formatDateTime } from '../utils/date'

const props = defineProps<{ currencyUnit: CurrencyUnit; suppliers: SupplierRecord[]; materials: MaterialRecord[] }>()
const emit = defineEmits<{ notify: [string] }>()
const rows = ref<PurchaseRecord[]>([])
const selectedId = ref<string | null>(null)
const loading = ref(false)
const error = ref('')
const editing = ref(false)
const form = ref<PurchasePayload>(blank())
const item = ref({ materialId: '', purchaseQuantity: '1', unitAcquisitionCostRial: '0', notes: '' })
const current = computed(() => rows.value.find((value) => value.id === selectedId.value) ?? null)

function blank(): PurchasePayload { return { supplierId: props.suppliers[0]?.id ?? '', purchaseDate: currentCanonicalDate(), supplierInvoiceNumber: '', notes: '', discountRial: 0, shippingRial: 0, taxRial: 0, additionalCostsRial: 0 } }
function dateOnly(value: string) { return value.slice(0, 10) }
onMounted(load)
async function load() { loading.value = true; try { rows.value = await purchasesApi.list() } catch (value) { error.value = String(value) } finally { loading.value = false } }
function select(value: PurchaseRecord) { selectedId.value = value.id; editing.value = value.status === 'Draft'; form.value = { supplierId: value.supplierId, purchaseDate: dateOnly(value.purchaseDate), supplierInvoiceNumber: value.supplierInvoiceNumber, notes: value.notes, discountRial: value.discountRial, shippingRial: value.shippingRial, taxRial: value.taxRial, additionalCostsRial: value.additionalCostsRial } }
async function create() { if (!props.suppliers.length) { error.value = 'Create a supplier before recording a purchase.'; return }; try { const value = await purchasesApi.create(blank()); rows.value = [value, ...rows.value]; select(value); emit('notify', 'Draft purchase created.') } catch (value) { error.value = String(value) } }
async function save() { if (!current.value) return; try { replace(await purchasesApi.update(current.value.id, form.value)); emit('notify', 'Purchase saved.') } catch (value) { error.value = String(value) } }
async function addItem() { if (!current.value) return; try { replace(await purchasesApi.addItem(current.value.id, item.value)); item.value = { materialId: '', purchaseQuantity: '1', unitAcquisitionCostRial: '0', notes: '' } } catch (value) { error.value = String(value) } }
async function removeItem(id: string) { if (!current.value) return; try { replace(await purchasesApi.removeItem(current.value.id, id)) } catch (value) { error.value = String(value) } }
async function reorder(index: number, direction: number) { if (!current.value) return; const items = [...current.value.items].sort((a, b) => a.position - b.position); const target = index + direction; if (target < 0 || target >= items.length) return; [items[index], items[target]] = [items[target], items[index]]; try { replace(await purchasesApi.reorder(current.value.id, items.map((value) => value.id))) } catch (value) { error.value = String(value) } }
async function post() { if (!current.value || !window.confirm('Post this purchase and create inventory movements?')) return; try { replace(await purchasesApi.post(current.value.id)); editing.value = false; emit('notify', 'Purchase posted.') } catch (value) { error.value = String(value) } }
async function cancel() { if (!current.value || !window.confirm('Cancel this posted purchase? This creates compensating movements.')) return; try { replace(await purchasesApi.cancel(current.value.id)); editing.value = false; emit('notify', 'Purchase cancelled with history preserved.') } catch (value) { error.value = String(value) } }
async function removeDraft() { if (!current.value || !window.confirm('Delete this draft permanently?')) return; try { await purchasesApi.deleteDraft(current.value.id); rows.value = rows.value.filter((value) => value.id !== current.value!.id); selectedId.value = null; emit('notify', 'Draft deleted.') } catch (value) { error.value = String(value) } }
function replace(value: PurchaseRecord) { rows.value = rows.value.map((item) => item.id === value.id ? value : item); selectedId.value = value.id; form.value = { supplierId: value.supplierId, purchaseDate: dateOnly(value.purchaseDate), supplierInvoiceNumber: value.supplierInvoiceNumber, notes: value.notes, discountRial: value.discountRial, shippingRial: value.shippingRial, taxRial: value.taxRial, additionalCostsRial: value.additionalCostsRial } }
</script>

<template>
  <div class="purchases-view">
    <WorkspaceStickyStack><header class="workspace-heading"><div><p class="eyebrow">Catalog / inventory</p><h1>Purchases</h1><p class="heading-description">Record supplier purchases, then post them into the immutable inventory ledger.</p></div><button class="button button-primary" @click="create"><Plus :size="16" /> New purchase</button></header></WorkspaceStickyStack>
    <div v-if="error" class="form-error" role="alert">{{ error }} <button class="icon-button" @click="error = ''" aria-label="Dismiss"><X :size="14" /></button></div>
    <section class="purchases-layout">
      <SectionPanel title="Purchase register" subtitle="Drafts are editable; posted history is protected."><div v-if="loading" class="materials-empty">Loading purchases…</div><div v-else-if="rows.length" class="table-wrap"><table class="data-table"><thead><tr><th>Purchase</th><th>Supplier</th><th>Date</th><th>Total</th><th>Paid</th><th>Remaining</th><th>Status</th></tr></thead><tbody><tr v-for="value in rows" :key="value.id" :class="{ 'is-selected': selectedId === value.id }" @click="select(value)"><td><span class="table-primary">{{ value.purchaseNumber }}</span><span class="table-secondary">{{ value.supplierInvoiceNumber || 'No invoice' }}</span></td><td>{{ value.supplierName }}</td><td>{{ formatDateTime(value.purchaseDate) }}</td><td>{{ formatMoney(value.totalRial, props.currencyUnit) }}</td><td>{{ formatMoney(value.paidRial || 0, props.currencyUnit) }}</td><td>{{ formatMoney(value.remainingRial ?? value.totalRial, props.currencyUnit) }}</td><td><StatusBadge :label="value.status" :tone="value.status === 'Posted' ? 'green' : value.status === 'Cancelled' ? 'slate' : 'amber'" /></td></tr></tbody></table></div><div v-else class="materials-empty"><ShoppingCart :size="22" /><p>No purchases yet.</p><button class="button button-secondary" @click="create"><Plus :size="15" /> Record purchase</button></div></SectionPanel>
      <SectionPanel v-if="current" title="Purchase editor" :subtitle="current.status === 'Draft' ? 'Draft purchase' : 'Historical purchase · read only'"><div class="purchase-status"><StatusBadge :label="current.status" :tone="current.status === 'Posted' ? 'green' : current.status === 'Cancelled' ? 'slate' : 'amber'" /><span>{{ current.purchaseNumber }}</span></div><form v-if="editing" class="purchase-form" @submit.prevent="save"><div class="material-form-grid"><label class="form-field"><span>Supplier</span><select v-model="form.supplierId" required><option value="" disabled>Select supplier</option><option v-for="value in props.suppliers" :key="value.id" :value="value.id">{{ value.name }}</option></select></label><label class="form-field"><span>Purchase date</span><JalaliDatePicker v-model="form.purchaseDate" placeholder="Select Jalali date" /></label></div><label class="form-field"><span>Supplier invoice</span><input v-model="form.supplierInvoiceNumber" /></label><div class="purchase-cost-grid"><label class="form-field"><span>Discount Rial</span><input v-model.number="form.discountRial" type="number" min="0" /></label><label class="form-field"><span>Shipping Rial</span><input v-model.number="form.shippingRial" type="number" min="0" /></label><label class="form-field"><span>Tax Rial</span><input v-model.number="form.taxRial" type="number" min="0" /></label><label class="form-field"><span>Additional Rial</span><input v-model.number="form.additionalCostsRial" type="number" min="0" /></label></div><label class="form-field"><span>Notes</span><textarea v-model="form.notes" rows="2" /></label><button class="button button-secondary" type="submit"><Save :size="15" /> Save metadata</button></form><div class="purchase-lines"><h3>Items <span>{{ current.items.length }}</span></h3><div v-for="(line, index) in [...current.items].sort((a, b) => a.position - b.position)" :key="line.id" class="purchase-line"><div><strong>{{ line.materialName }}</strong><small>{{ line.purchaseQuantity }} {{ line.purchaseUnit }} → {{ line.consumptionQuantity }} {{ line.consumptionUnit }}</small></div><span>{{ formatMoney(line.lineTotalRial, props.currencyUnit) }}</span><span v-if="editing" class="line-reorder"><button class="icon-button" :disabled="index === 0" aria-label="Move line up" @click="reorder(index, -1)"><ArrowUp :size="13" /></button><button class="icon-button" :disabled="index === current.items.length - 1" aria-label="Move line down" @click="reorder(index, 1)"><ArrowDown :size="13" /></button></span><button v-if="editing" class="icon-button" @click="removeItem(line.id)" aria-label="Remove item"><Trash2 :size="14" /></button></div><form v-if="editing" class="purchase-add-line" @submit.prevent="addItem"><select v-model="item.materialId" required><option value="" disabled>Material</option><option v-for="value in props.materials" :key="value.id" :value="value.id">{{ value.name }}</option></select><input v-model="item.purchaseQuantity" required placeholder="Qty" inputmode="decimal" /><input v-model="item.unitAcquisitionCostRial" required placeholder="Unit cost Rial" inputmode="numeric" /><button class="button button-secondary"><Plus :size="15" /> Add line</button></form></div><dl class="purchase-totals"><div><dt>Subtotal</dt><dd>{{ formatMoney(current.subtotalRial, props.currencyUnit) }}</dd></div><div><dt>Discount / costs</dt><dd>{{ formatMoney(current.discountRial, props.currencyUnit) }} / {{ formatMoney(current.shippingRial + current.taxRial + current.additionalCostsRial, props.currencyUnit) }}</dd></div><div><dt>Total</dt><dd>{{ formatMoney(current.totalRial, props.currencyUnit) }}</dd></div></dl><div class="inspector-actions"><button v-if="current.status === 'Draft'" class="button button-primary" @click="post"><Check :size="15" /> Post purchase</button><button v-if="current.status === 'Draft'" class="button button-danger" @click="removeDraft"><Trash2 :size="15" /> Delete draft</button><button v-if="current.status === 'Posted'" class="button button-secondary" @click="cancel">Cancel / reverse</button></div></SectionPanel>
      <SectionPanel v-else title="Purchase inspector" subtitle="Select a purchase or start a new draft."><div class="inspector-empty-copy"><ShoppingCart :size="20" /><p>Purchase details will appear here.</p></div></SectionPanel>
    </section>
  </div>
</template>
